# leetcode 567

import copy
from collections import defaultdict

class Solution:
	'''
	Approach, sliding window
	Similar pattern we did for minimum window substring leetcode 76
	Count the letters using a hashmap for s1.
	Initialize two pointers left and right as 0
	Then increase right and see if the letter exists in the s1 map. Decrease the letters until it gets 0
	If the letter gets -ve decrement that means the presence of the letter is more than expected
	Move left pointer until the current s2[right] gets a positive value, means we moved our left pointer and passed
	the extra letter position.
	If the letter does not exist in the map then simply move the left pointer near to the right
	so that we process can start over
	Time complexity: O(s1 * s2) // because of s1AllCovered
	Space complexity: O(s1 + s2)
	'''
	def checkInclusion(self, s1: str, s2: str) -> bool:

		def s1AllCovered(s1Dict: defaultdict) -> bool:
			for k, v in s1Dict.items():
				if v > 0:
					return False
			return True

		s1Dict = defaultdict(int)

		for char in s1:
			s1Dict[char] += 1

		left, right = 0, 0

		while left < len(s2) and right < len(s2):
			if (s2[right] in s1Dict) and ((s1Dict[s2[right]] - 1) >= 0):
				s1Dict[s2[right]] -= 1

				if s1AllCovered(s1Dict) == True:
					return True

				right += 1
			elif (s2[right] in s1Dict) and ((s1Dict[s2[right]] - 1) < 0):
				while left < right:
					if s2[left] in s1Dict:
						s1Dict[s2[left]] += 1
					left += 1

					if s1Dict[s2[right]] > 0:
						break
			else:
				while left < right:
					if s2[left] in s1Dict:
						s1Dict[s2[left]] += 1
					left += 1
				right += 1

		return False


obj = Solution()

